import unittest

from foi import kq_trivial_types as ktt
from foi import kq_trivial_sug as kqs
from pycmn import bib_locales as tbn
from pycmn import uni_denorm as udn
from pycmn import ws_tmpl1 as wtp1
from pycmn import ws_tmpl2 as wtp
from ws import ws_bot_edit_kq_triv_add_type as mod


def _trivial_tmpl(pointed_ketiv, unpointed_ketiv, pointed_qere, sug=None):
    elements = [
        ['מ:קו"כ-אם-2'],
        [pointed_ketiv],
        [unpointed_ketiv],
        [pointed_qere],
    ]
    if sug is not None:
        elements.append([f"סוג={sug}"])
    return wtp1.mktmpl(elements)


def _pqere(tmpl):
    return udn.give_std_mark_order(ktt.pointed_qere_text(wtp.use_tmpl2(tmpl)))


def _set_ctx(book39, chapter, verse):
    mod._ctx["bk39id"] = book39
    mod._ctx["he_chnu"] = ""
    mod._ctx["chapter"] = chapter
    mod._ctx["he_vrnu"] = ""
    mod._ctx["verse"] = verse


def _bcv_short(book39, chapter, verse):
    return tbn.short_bcv((book39, chapter, verse))


class WsBotKqTrivialAddTypeTests(unittest.TestCase):
    def setUp(self):
        mod._warnings.clear()
        mod._subtypes_by_bcv_pqere = {}

    def test_subtype_to_sug_mapping_for_all_five_named_subtypes(self):
        cases = [
            (
                _trivial_tmpl("עֹֽלוֹתָ֔ו", "עלותו", "עֹֽלוֹתָ֔יו"),
                ktt.QYV,
            ),
            (
                _trivial_tmpl("מָרִ֕אי", "מראי", "מָרִ֕י"),
                ktt.EXTRA_ALEF,
            ),
            (
                _trivial_tmpl("הַהִ֖וא", "ההוא", "הַהִ֖יא"),
                ktt.HI_SPELLED_HU,
            ),
            (
                _trivial_tmpl("הַֽנַּעֲרָ֖", "הנער", "הַֽנַּעֲרָ֖ה"),
                ktt.N3RH_SPELLED_N3R,
            ),
            (
                _trivial_tmpl("סוּתֹֽה", "סותה", "סוּתֽוֹ"),
                ktt.XOLAM_HE,
            ),
        ]
        for idx, (tmpl, subtype) in enumerate(cases, start=1):
            with self.subTest(subtype=subtype):
                _set_ctx("Joshua", 1, idx)
                bcv_short = _bcv_short("Joshua", 1, idx)
                mod._subtypes_by_bcv_pqere = {(bcv_short, _pqere(tmpl)): subtype}
                expected_sug = kqs.SUG_TEXT_BY_SUBTYPE[subtype]

                transformed = mod._transform_kq_triv_add_type(tmpl)[0]
                transformed2 = wtp.use_tmpl2(transformed)

                self.assertEqual(
                    wtp.template_param_val(transformed2, "סוג"), [expected_sug]
                )

    def test_misc_leaves_template_unchanged(self):
        tmpl = _trivial_tmpl("סוּתֹֽה", "סותה", "סוּתִֽי")
        _set_ctx("Joshua", 2, 1)
        bcv_short = _bcv_short("Joshua", 2, 1)
        mod._subtypes_by_bcv_pqere = {(bcv_short, _pqere(tmpl)): ktt.MISC}

        transformed = mod._transform_kq_triv_add_type(tmpl)[0]

        self.assertEqual(transformed, tmpl)
        self.assertEqual(mod.get_warnings(), [])

    def test_existing_sug_is_not_overwritten_and_warns(self):
        tmpl = _trivial_tmpl("עֹֽלוֹתָ֔ו", "עלותו", "עֹֽלוֹתָ֔יו", sug="ישן")
        _set_ctx("Joshua", 3, 1)
        bcv_short = _bcv_short("Joshua", 3, 1)
        mod._subtypes_by_bcv_pqere = {(bcv_short, _pqere(tmpl)): ktt.QYV}

        transformed = mod._transform_kq_triv_add_type(tmpl)[0]

        self.assertEqual(transformed, tmpl)
        self.assertEqual(len(mod.get_warnings()), 1)
        warning = mod.get_warnings()[0]
        self.assertEqual(warning["reason"], "existing-sug")
        self.assertIn('{{מ:קו"כ-אם-2', warning["old_tmpl_text"])

    def test_idempotence_on_repeated_application(self):
        tmpl = _trivial_tmpl("עֹֽלוֹתָ֔ו", "עלותו", "עֹֽלוֹתָ֔יו")
        _set_ctx("Joshua", 4, 1)
        bcv_short = _bcv_short("Joshua", 4, 1)
        mod._subtypes_by_bcv_pqere = {(bcv_short, _pqere(tmpl)): ktt.QYV}

        first = mod._transform_kq_triv_add_type(tmpl)[0]
        second = mod._transform_kq_triv_add_type(first)[0]

        self.assertEqual(first, second)

    def test_concordance_passes_when_classifier_matches_foi(self):
        tmpl = _trivial_tmpl("הַהִ֖וא", "ההוא", "הַהִ֖יא")
        _set_ctx("Joshua", 5, 1)
        bcv_short = _bcv_short("Joshua", 5, 1)
        mod._subtypes_by_bcv_pqere = {(bcv_short, _pqere(tmpl)): ktt.HI_SPELLED_HU}

        transformed = mod._transform_kq_triv_add_type(tmpl)[0]

        transformed2 = wtp.use_tmpl2(transformed)
        self.assertEqual(
            wtp.template_param_val(transformed2, "סוג"),
            ["כתיב הוא קרי היא"],
        )

    def test_concordance_fails_when_foi_key_missing(self):
        tmpl = _trivial_tmpl("הַהִ֖וא", "ההוא", "הַהִ֖יא")
        _set_ctx("Joshua", 6, 1)

        with self.assertRaises(AssertionError) as ctx:
            mod._transform_kq_triv_add_type(tmpl)

        self.assertIn("Missing FOI subtype", str(ctx.exception))
        self.assertIn("bcv_short", str(ctx.exception))
        self.assertIn("pqere", str(ctx.exception))

    def test_concordance_fails_when_subtype_mismatches(self):
        tmpl = _trivial_tmpl("הַהִ֖וא", "ההוא", "הַהִ֖יא")
        _set_ctx("Joshua", 7, 1)
        bcv_short = _bcv_short("Joshua", 7, 1)
        mod._subtypes_by_bcv_pqere = {(bcv_short, _pqere(tmpl)): ktt.EXTRA_ALEF}

        with self.assertRaises(AssertionError) as ctx:
            mod._transform_kq_triv_add_type(tmpl)

        self.assertIn("FOI/classifier subtype mismatch", str(ctx.exception))
        self.assertIn("classifier_subtype", str(ctx.exception))
        self.assertIn("foi_subtype", str(ctx.exception))


if __name__ == "__main__":
    unittest.main()
